#ifndef SCREAMER_SERIAL_OP_REGISTRY_H
#define SCREAMER_SERIAL_OP_REGISTRY_H

// The operator registry: every operator built by name from its settings, the
// "settings" object of a save file. src/screamer/serial/op_registry.cpp is
// generated by devtools/gen_op_registry.py from screamer/data/help.json and
// devtools/wasm/wasm_manifest.json.
//
// make_op applies the renamed settings first (serial/settings_compat.h). A
// setting that is missing or null takes the constructor's default (an
// optional setting stays unset), and a nested operator setting is the object
// {"type": T, "settings": {...}}. An unknown type or parameter, a value of
// the wrong kind and a value the constructor refuses raise SaveError, with
// the path of the setting: "RollingMean.settings.window_size: ...".

#include <memory>
#include <string>
#include <vector>

#include "screamer/common/eval_op.h"
#include "screamer/common/json.h"

namespace screamer { namespace serial {

// A fresh operator of type `type` built from `settings`; `path` names the
// node in errors ("object" for the top of a file).
std::unique_ptr<EvalOp> make_op(const std::string& type, const json::Value& settings,
                                 const std::string& path = "object");

// The names make_op knows, sorted.
std::vector<std::string> registry_types();

}}  // namespace screamer::serial

#endif  // SCREAMER_SERIAL_OP_REGISTRY_H
